enum class Alert : std::uint8_t { none, defend_group, avoid_group, contest_altar };

constexpr std::array<vec2, 8> kDirs{
    vec2{0, 1}, vec2{1, 1}, vec2{1, 0}, vec2{1, -1},
    vec2{0, -1}, vec2{-1, -1}, vec2{-1, 0}, vec2{-1, 1},
};

int distance(vec2 a, vec2 b) { return static_cast<int>(a.chebyshev_distance(b)); }
int line_sq(vec2 a, vec2 b) { const int dx = a.x - b.x, dy = a.y - b.y; return dx * dx + dy * dy; }  // squared straight-line distance (kDashLine)

// Spells that deal damage. Tavi's, Prism's and Ren's stunning spells are crowd
// control to the engine but hit for 2.2 / 1.5 / 1.25 x Focus.
// kDashDamage: a dash that hits where it lands (Heart of Ruin); a movement-only dash has modifier 0.
template <class Ability>
bool damaging_dash(const Ability& ab) {
    if (!kDashDamage || !ab.is_dash()) return false;
    const auto& info = ab.info();
    if (!info) return false;
    const auto* d = std::get_if<cambc::ability_dash>(&*info);
    return d && d->modifier > 0;
}

template <class Ability>
bool deals_damage(const Ability& ab, int part) {
    return ab.is_damage() || ab.is_aoe_damage() || damaging_dash(ab) || ((kSpellDpsFix & part) != 0 && ab.is_cc());
}

// The geometric reach of a targeted or area spell (0 for kinds without one).
template <class Ability>
int ability_reach(const Ability& ab) {
    const auto& info = ab.info();
    if (!info) return 0;
    if (kDashDamage) {
        if (const auto* d = std::get_if<cambc::ability_dash>(&*info)) return static_cast<int>(d->range + (d->modifier > 0 ? d->radius : 0.0f));
    }
    return std::visit([](const auto& v) -> int {
        if constexpr (requires { v.range; }) return static_cast<int>(v.range);
        else return 0;
    }, *info);
}

// Casting it rules out normal movement this round.
template <class Ability>
bool excludes_movement(const Ability& ab) {
    const auto& info = ab.info();
    return info && std::visit([](const auto& v) { return v.exclusive_with_movement; }, *info);
}

// Run an engine action, treating any SDK error as "did not happen".
template <class F>
bool attempt(F&& f) {
    try {
        return f();
    } catch (const std::exception&) {
        return false;
    }
}

struct Monster {
    float hp = 0;
    float str = 0;
    int range = 3;  // attack range (Monolith 5)
};

struct Group {
    std::vector<vec2> tiles;  // original spawn tiles
    std::vector<Monster> monsters;
    vec2 center;
    float gems = 0;
    float gold = 0;
    float total_hp = 0;
    float threat = 0;         // fight_cost x dps, fixed per group
    int original_hitters = 0; // kCacheStaticHitters: members with base strength > 0 (the member list never changes)
    int packed = 1;           // most monsters within one tile of one of them (splash targets)
    bool has_elk = false;
    bool hostile = false;     // any member hits back
    float neighbours = 0;     // gems + gold/4 of the other groups within 12 tiles
    float respawn = 40;       // rounds from capture to respawn (the group's longest member cooldown)
};

// Map analysis: what wins this map, from its camps alone (no map names). At round 2000 ties go to banked gems,
// then lifetime gold earned, then kills; so where the gems sit decides the plan.
enum class MapPlan { race, boss, gem_count, gold_tiebreak };
struct MapProfile {
    // camp classes: 0 harmless (clusters), 1 light (strength sum <= 40, under 5000 health), 2 heavy, 3 boss (10000+ health)
    float gems[4] = {0, 0, 0, 0}, gold[4] = {0, 0, 0, 0}, gem_rate[4] = {0, 0, 0, 0}, gold_rate[4] = {0, 0, 0, 0};
    int count[4] = {0, 0, 0, 0};
    float our_gem_rate = 0;        // non-boss gems per round on our half if every camp is retaken at respawn
    float all_gem_rate = 0;        // ... on the whole map
    float gold_only_gold = 0;      // gold in groups that drop no gems
    float bound_rounds = 1e9f;     // rounds to winning_gems from our half's non-boss camps at that rate (a lower bound)
    MapPlan plan = MapPlan::race;
};
const char* plan_name(MapPlan p) {
    return p == MapPlan::race ? "race" : p == MapPlan::boss ? "boss" : p == MapPlan::gem_count ? "gem_count" : "gold_tiebreak";
}

enum class Known { unknown, alive, reward, respawning };

// A chosen camp group and the gems per round each champion on it earns.
struct Pick {
    int group = -1;
    float score = 0;
};

// Camp spawn tile -> group index on a flat grid, with the std::map calls the bot uses (count, find/end, iteration):
// a std::map insert costs ~700 fuel and set-up inserted every camp tile (~83k of lanes' set-up with the vectors).
class TileGroups {
public:
    using Entry = std::pair<vec2, int>;
    void init(int w, int h) {
        w_ = w;
        h_ = h;
        index_.assign(static_cast<std::size_t>(std::max(0, w * h)), -1);
        entries_.clear();
    }
    void set(vec2 p, int group) {
        if (!inside(p)) return;
        int& k = index_[cell(p)];
        if (k < 0) {
            k = static_cast<int>(entries_.size());
            entries_.push_back({p, group});
        } else {
            entries_[static_cast<std::size_t>(k)].second = group;
        }
    }
    void reserve(std::size_t n) { entries_.reserve(n); }  // kSetupFuel 4
    std::size_t count(vec2 p) const { return inside(p) && index_[cell(p)] >= 0 ? 1 : 0; }
    const Entry* find(vec2 p) const { return inside(p) && index_[cell(p)] >= 0 ? entries_.data() + index_[cell(p)] : end(); }
    const Entry* begin() const { return entries_.data(); }
    const Entry* end() const { return entries_.data() + entries_.size(); }

private:
    bool inside(vec2 p) const { return p.x >= 0 && p.y >= 0 && p.x < w_ && p.y < h_; }
    std::size_t cell(vec2 p) const { return static_cast<std::size_t>(p.y * w_ + p.x); }
    int w_ = 0, h_ = 0;
    std::vector<int> index_;
    std::vector<Entry> entries_;
};

struct Field {
    cambc::distance_field dist;
    cambc::bitboard reach;
    std::uint32_t gen = 0;  // build number (kSafeRoute: a walled copy is rebuilt when its base field was)
    std::uint32_t epoch = 0;  // kCampRoute: the camp epoch a camp-blocked copy was built in
    // kFieldLin (edit_fieldlin.py): a row-major copy of dist / reach for fields never changed after they are built
    bool lin_ok = false;                                   // set by the builders that store into fields_
    std::uint16_t cap = 0;                                 // kFieldCap (edit_fieldcap.py): max_distance of a capped compute (0: full)
    int group = -1;                                        // ... the camp group of a capped approach field
    mutable std::uint32_t lin_reads = 0;
    mutable std::unique_ptr<std::uint16_t[]> lin_d;        // exported distances (uninitialised until the export)
    mutable std::unique_ptr<std::uint8_t[]> lin_r;         // exported reach board, bit-packed row-major (cambc.h: LSB first)
};

// Damage a team takes clearing a group, killing the most dangerous monster per
// health point first and assuming every live monster hits once per round. The
// kill order does not depend on our damage, so this is a per-group constant
// divided by it.
float group_threat_sorted(std::vector<Monster>& ms);
float group_threat(const std::vector<Monster>& in) {  // kSetupFuel 1: no per-call vector allocation (edit_setupfuel.py)
    if (kSetupFuel & 1) {
        static std::vector<Monster> scratch;
        scratch.assign(in.begin(), in.end());
        return group_threat_sorted(scratch);
    }
    std::vector<Monster> ms = in;
    return group_threat_sorted(ms);
}
float group_threat_sorted(std::vector<Monster>& ms) {
    std::sort(ms.begin(), ms.end(), [](const Monster& a, const Monster& b) {
        return a.str * b.hp > b.str * a.hp;
    });
    float hp = 0, dmg = 0;
    for (const Monster& m : ms) {
        hp += m.hp;
        dmg += m.str * hp;
    }
    return dmg;
}


float group_value(const Group& g) { return g.gems + kGoldWeight * g.gold; }
int elk_count(const Group& g) {
    int n = 0;
    for (const auto& m : g.monsters) n += m.hp >= 2000.0f && m.hp <= 3000.0f ? 1 : 0;
    return n;
}

// Shard to buy for each emblem in order; five shards combine into one emblem.
// Mirrors the top ladder teams: Monster first (more camp damage), then Jungle
// health (less camp damage taken), then Power and Durability alternating.
// kBuild2: the champion's 2.0.0 top-team line, empty when its bit is off.
std::vector<cambc::item_type> build2_plan(cambc::champion_type type) {
    using cambc::champion_type;
    using cambc::item_type;
    if (kBuild3 > 0) {  // kBuild3: the top 5 teams' lines (see edit_build3.py)
        const item_type th = item_type::treasure_shard_of_health, ts = item_type::treasure_shard_of_strength, tf = item_type::treasure_shard_of_focus;
        const item_type js = item_type::jungle_shard_of_strength, jf = item_type::jungle_shard_of_focus, jh = item_type::jungle_shard_of_health;
        const item_type bh = item_type::bruiser_shard_of_health, bs = item_type::bruiser_shard_of_strength;
        const item_type dh = item_type::durability_shard_of_health, df = item_type::durability_shard_of_focus;
        const item_type ms = item_type::monster_shard_of_strength, mh = item_type::monster_shard_of_health;
        const item_type ps = item_type::power_shard_of_strength, pf = item_type::power_shard_of_focus, hh = item_type::home_shard_of_health;
        if ((kBuild3 & 1) && type == champion_type::marcella) return {th, js, bh, dh, bs};
        if ((kBuild3 & 2) && type == champion_type::ryth) return {js, bh, dh};
        if ((kBuild3 & 4) && type == champion_type::vesper_vale) return {ts, js, bh, bs, dh};
        if ((kBuild3 & 8) && type == champion_type::heart_of_ruin) return {th, jf, bh, bh};
        if ((kBuild3 & 16) && type == champion_type::willow) return {dh, bh, tf};
        if ((kBuild3 & 32) && type == champion_type::vendetta) return {ms, jh, ps, ps};
        if (kBuild3 & 64) {
            if (type == champion_type::varg) return {ms, jh, ps};
            if (type == champion_type::prism) return {dh, mh, jh};
            if (type == champion_type::tavi) return {th, ts, bs, ms, dh};
            if (type == champion_type::cassi) return {tf, jf, df, bh};
            if (type == champion_type::issac) return {ts, ps, hh};
            if (type == champion_type::stellar) return {tf, pf, hh};
            if (type == champion_type::ren) return {bh};
        }
    }
    const item_type th = item_type::treasure_shard_of_health, ts = item_type::treasure_shard_of_strength, tf = item_type::treasure_shard_of_focus;
    const item_type js = item_type::jungle_shard_of_strength, jf = item_type::jungle_shard_of_focus, jh = item_type::jungle_shard_of_health;
    const item_type bh = item_type::bruiser_shard_of_health, bs = item_type::bruiser_shard_of_strength;
    const item_type dh = item_type::durability_shard_of_health, df = item_type::durability_shard_of_focus;
    const item_type ms = item_type::monster_shard_of_strength, mh = item_type::monster_shard_of_health;
    const item_type ps = item_type::power_shard_of_strength, pf = item_type::power_shard_of_focus, hh = item_type::home_shard_of_health;
    if (kRuinBuild > 0 && type == champion_type::heart_of_ruin) {  // kRuinBuild
        const item_type bf = item_type::bruiser_shard_of_focus;
        if (kRuinBuild == 1) return {th, jf, bf};
        if (kRuinBuild == 2) return {jf, bf, bh};
        if (kRuinBuild == 4) return {th, jf, bf, bh, bf, bh, bf, bh, bf, bh, bf, bh};
        if (kRuinBuild == 5) return {th, jf, bh};  // edit_ruinhp.py: health-heavy lines (the last entry stacks forever)
        if (kRuinBuild == 6) return {th, item_type::jungle_shard_of_health, bh};
        if (kRuinBuild == 7) return {th, bh, item_type::durability_shard_of_health, bh};
        return {tf, jf, bf};
    }
    if (kVespMix > 0 && type == champion_type::vesper_vale) {  // kVespMix
        std::vector<item_type> v{ts, js};
        if (kVespMix == 2) v.push_back(bh);
        for (int i = 0; i < 6; ++i) v.insert(v.end(), {bs, bs, bh});
        return v;
    }
    if (kRythMix > 0 && type == champion_type::ryth) {  // kRythMix
        std::vector<item_type> v{th, jh};
        for (int i = 0; i < 6; ++i) {
            if (kRythMix == 1) v.insert(v.end(), {bh, bh, bs});
            else v.insert(v.end(), {bh, bs});
        }
        return v;
    }
    if (kVendBuild > 0 && type == champion_type::vendetta) {  // kVendBuild
        const item_type prs = item_type::prospector_shard_of_strength, hs = item_type::hunter_shard_of_strength;
        if (kVendBuild == 1) return {ts, prs, jh, bs, bh, bs, bh, bs, bh, bs, bh, bs};
        return {hs, js, dh, bs, bh, bs, bh, bs, bh, bs, bh, bs};
    }
    if ((kBuild2 & 1) && type == champion_type::marcella) return {th, js, bh};
    if ((kBuild2 & 2) && type == champion_type::ryth) return {th, js, bh};
    if ((kBuild2 & 4) && type == champion_type::vesper_vale) return {ts, js, bh};
    if ((kBuild2 & 8) && type == champion_type::heart_of_ruin) return {th, jf, bh};
    if ((kBuild2 & 16) && type == champion_type::willow) return {dh, bh, tf};
    if ((kBuild2 & 32) && type == champion_type::vendetta) return {th, js, bh};
    if (kBuild2 & 64) {
        if (type == champion_type::prism) return {dh, mh, jh};
        if (type == champion_type::tavi) return {bs, dh, ms};
        if (type == champion_type::varg) return {js, ts, dh};
        if (type == champion_type::issac) return {ts, ps, hh};
        if (type == champion_type::stellar) return {tf, pf, hh};
        if (type == champion_type::cassi) return {pf, df, bh};
    }
    return {};
}

