    // Chebyshev distance to a set of tiles: a corner formula when they fill
    // their bounding box (spawn regions), else a scan of every tile.
    struct Region {
        std::vector<vec2> tiles;
        vec2 lo{0, 0}, hi{-1, -1};
        bool box = false;
        void set(std::vector<vec2> t) {
            tiles = std::move(t);
            if (tiles.empty()) return;
            lo = hi = tiles.front();
            for (const vec2 p : tiles) {
                lo = vec2{std::min(lo.x, p.x), std::min(lo.y, p.y)};
                hi = vec2{std::max(hi.x, p.x), std::max(hi.y, p.y)};
            }
            box = static_cast<long long>(tiles.size()) == static_cast<long long>(hi.x - lo.x + 1) * (hi.y - lo.y + 1);
        }
        int dist(vec2 p) const {
            if (tiles.empty()) return 1 << 20;
            if (box) {
                const int dx = std::max({lo.x - p.x, p.x - hi.x, 0});
                const int dy = std::max({lo.y - p.y, p.y - hi.y, 0});
                return std::max(dx, dy);
            }
            int best = 1 << 20;
            for (const vec2 t : tiles) best = std::min(best, distance(p, t));
            return best;
        }
    };
    Region home_region_, enemy_region_;
