    cambc::bitboard bush_bits_;  // kScoutWindow (edit_postguard.py)
    cambc::bitboard bush_bb_;  // kBushGhost
    bool near_bush(vec2 p) const {
        for (int dx = -1; dx <= 1; ++dx) {
            for (int dy = -1; dy <= 1; ++dy) {
                const vec2 q = p + off(dx, dy);
                if (cambc::map::is_in_bounds(q) && bush_bb_.is_set(q)) return true;
            }
        }
        return false;
    }
